<template>
  <article class="music-detail-card">
    <header id="sec-chart-info" class="top-info">
      <p class="music-chapter">{{ dict.chapter || '-' }}</p>
      <h2 class="music-name">{{ dict.name || '-' }}</h2>
      <p class="music-composer">{{ dict.composer || '-' }}</p>
    </header>

    <figure class="image-container">
      <img
        :src="imagePath"
        :alt="dict.name || '曲绘'"
        class="illustration-image"
      />
    </figure>

    <p class="music-illustrator" title="曲绘">{{ dict.illustrator || '-' }}</p>

    <!-- 侧栏「谱面数据」这一组的锚点落在这里（组 = 基本信息 + 难度与物量） -->
    <div id="grp-chart-data" class="chart-data">
      <dl id="sec-basic" class="info-grid">
        <div v-for="(field, index) in otherFields" :key="index" class="info-item">
          <dt class="info-label">{{ field.label }}</dt>
          <dd class="info-value">{{ dict[field.key] || '-' }}</dd>
        </div>
      </dl>

      <section id="sec-difficulty" class="difficulty-section">
        <div class="table-wrapper">
          <table class="dt-table difficulty-table">
            <thead>
              <tr>
                <th>难度</th>
                <th>定数</th>
                <th>物量</th>
                <th>谱师名义</th>
                <th>谱师</th>
                <th class="num">Tap</th>
                <th class="num">Drag</th>
                <th class="num">Hold</th>
                <th class="num">Flick</th>
                <th class="num">Line</th>
              </tr>
            </thead>
            <tbody>
              <tr
                v-for="(item, index) in validDifficultyData"
                :key="index"
              >
                <td>
                  <span class="dt-diff" :class="`dt-diff--${item.diffName.toLowerCase()}`">{{ item.diffName }}</span>
                </td>
                <td class="num strong">{{ item.data.lvl || '-' }}</td>
                <td class="num">{{ item.data.notecount || '-' }}</td>
                <td>{{ item.data.charter || '-' }}</td>
                <td>{{ item.data.tcharter || '-' }}</td>
                <td class="num">{{ item.data.tap ?? '-' }}</td>
                <td class="num">{{ item.data.drag ?? '-' }}</td>
                <td class="num">{{ item.data.hold ?? '-' }}</td>
                <td class="num">{{ item.data.flick ?? '-' }}</td>
                <td class="num">{{ item.data.line ?? '-' }}</td>
              </tr>
            </tbody>
          </table>
        </div>
        <p v-if="!validDifficultyData.length" class="dt-empty">该曲目暂无谱面数据</p>
      </section>
    </div>
  </article>
</template>

<script setup>
import { defineProps, ref, computed, onMounted, onUnmounted } from 'vue'
import { useRemScale } from '../../utils/rem.js'

import { setAnchorNav, clearAnchorNav } from '../../composables/useAnchorNav.js'

useRemScale()

// 详情页的分区（渲染成侧栏二级目录，点它滚到对应锚点）
const ANCHOR_NAV = [
  { id: 'sec-chart-info', label: '曲目信息', icon: 'music-circle-outline' },
  {
    id: 'grp-chart-data',
    label: '谱面数据',
    icon: 'table-large',
    children: [
      { id: 'sec-basic', label: '基本信息', icon: 'information-outline' },
      { id: 'sec-difficulty', label: '难度与物量', icon: 'chart-bar' }
    ]
  }
]

const otherFields = [
  { label: '更新', key: 'date' },
  { label: '版本', key: 'version' },
  { label: 'BPM', key: 'BPM' },
  { label: '时长', key: 'duration' },
  { label: '关联', key: 'relation' },
  { label: '赛事', key: 'competition'}
];

const difficultyKeys = ['EZ', 'HD', 'IN', 'AT', 'LY', 'SP'];

const props = defineProps({
  dict: {
    type: Object,
    required: true,
    default: () => ({})
  }
})

const imagePath = ref('')
const isImageError = ref(false)

onMounted(() => {
  initImage()
  setAnchorNav(ANCHOR_NAV)
})

onUnmounted(() => {
  clearAnchorNav()
})

const getIllAssetsPath = computed(() => {
  if (props.dict?.illAssets && typeof props.dict.illAssets === 'string') {
    return props.dict.illAssets
  }
  return ''
})

const difficultyTypes = computed(() => {
  const result = {};
  difficultyKeys.forEach(key => {
    result[key] = props.dict[key] || {};
  });
  return result;
});

const validDifficultyData = computed(() => {
  const validData = [];
  for (const diffName of difficultyKeys) {
    const diffData = difficultyTypes.value[diffName] || {};
    if (!isDiffEmpty(diffData)) {
      validData.push({
        diffName,
        data: diffData
      });
    }
  }
  return validData;
});

const isDiffEmpty = (diffData) => {
  return !diffData.tcharter && !diffData.dif && !diffData.lvl && !diffData.notecount;
}

const initImage = () => {
  imagePath.value = getIllAssetsPath.value
  isImageError.value = false
}
</script>

