<template>
  <div class="chart-card">
    <div class="card-cover">
      <img
        :src="chartInfo[2]"
        :alt="chartInfo[0]"
        class="cover-img"
        @load="handleImageLoad"
        @error="handleImageError"
      >
      <div v-if="!imageLoaded" class="alt-placeholder">{{ chartInfo[0] }}</div>
    </div>
    <!-- 曲名压在曲绘上方但文字完全透明，看不见，只给浏览器 Ctrl+F 搜索定位 -->
    <span class="dt-cover-name">{{ chartInfo[3] }}</span>
  </div>
</template>

<script setup>
import { ref } from 'vue';

/*
 * 曲目列表里的封面砖：只画曲绘。chartInfo 字段顺序由 api/infos.js 的 getSongGroups 决定：
 * [曲目键名, 章节, 曲绘地址, 曲名]；曲名不显示，只作为不可见文本给 Ctrl+F 用。
 */
const props = defineProps({
  chartInfo: {
    type: Array,
    required: true
  }
});

const imageLoaded = ref(false);

const handleImageLoad = () => {
  imageLoaded.value = true;
};

const handleImageError = () => {
  imageLoaded.value = false;
};
</script>

